def solve_task(input_grid):
    """
    Apply the pattern: inner color expands outward, border takes the space in between
    """
    h = len(input_grid)
    w = len(input_grid[0])

    # Get all non-zero cells by color
    cells_by_color = {}
    for i in range(h):
        for j in range(w):
            c = input_grid[i][j]
            if c not in cells_by_color:
                cells_by_color[c] = []
            cells_by_color[c].append((i, j))

    colors = [c for c in cells_by_color.keys() if c != 0]
    print(f"Colors in input: {colors}")

    # Find border color using cells adjacent to 0
    border_cells = []
    for i in range(h):
        for j in range(w):
            if input_grid[i][j] != 0:
                has_zero_neighbor = False
                for di, dj in [(-1,0), (1,0), (0,-1), (0,1)]:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < h and 0 <= nj < w:
                        if input_grid[ni][nj] == 0:
                            has_zero_neighbor = True
                            break
                    if (di == 0 and nj < 0) or (di == 0 and nj >= w) or (dj == 0 and ni < 0) or (dj == 0 and ni >= h):
                        has_zero_neighbor = True
                        break
                if has_zero_neighbor:
                    border_cells.append((i, j))

    print(f"Border cells found: {len(border_cells)}")

    # Most common color among border cells
    border_cell_colors = [input_grid[i][j] for (i, j) in border_cells]
    border_color_counts = {}
    for c in border_cell_colors:
        border_color_counts[c] = border_color_counts.get(c, 0) + 1

    print(f"Border cell colors: {border_color_counts}")
    border_color = max(border_color_counts.keys(), key=lambda x: border_color_counts[x])
    inner_color = [c for c in colors if c != border_color and c != 0][0]

    print(f"Final: border={border_color}, inner={inner_color}")

    # Find the bounding box of inner color cells
    inner_min_r, inner_min_c = h, w
    inner_max_r, inner_max_c = -1, -1

    for i in range(h):
        for j in range(w):
            if input_grid[i][j] == inner_color:
                inner_min_r = min(inner_min_r, i)
                inner_min_c = min(inner_min_c, j)
                inner_max_r = max(inner_max_r, i)
                inner_max_c = max(inner_max_c, j)

    print(f"Inner region: ({inner_min_r}, {inner_min_c}) to ({inner_max_r}, {inner_max_c})")

    # Create output grid
    output_grid = [[0 for _ in range(w)] for _ in range(h)]

    # Expand inner region by 1 in all directions
    new_inner_min_r = max(0, inner_min_r - 1)
    new_inner_min_c = max(0, inner_min_c - 1)
    new_inner_max_r = min(h - 1, inner_max_r + 1)
    new_inner_max_c = min(w - 1, inner_max_c + 1)

    print(f"New inner region: ({new_inner_min_r}, {new_inner_min_c}) to ({new_inner_max_r}, {new_inner_max_c})")

    # Fill the expanded region with inner color
    for i in range(new_inner_min_r, new_inner_max_r + 1):
        for j in range(new_inner_min_c, new_inner_max_c + 1):
            output_grid[i][j] = inner_color

    # Fill the space between old inner boundary with border color
    for i in range(inner_min_r, inner_max_r + 1):
        for j in range(inner_min_c, inner_max_c + 1):
            if output_grid[i][j] == 0:
                output_grid[i][j] = border_color

    return output_grid

